// src/assets/favicon.js
// Self-hosted brand assets: the JobForion logo (embedded raster, wrapped in
// SVG for /favicon.svg so it still serves valid image/svg+xml) + base64
// PNG/ICO variants for every platform + <head> icon links.

// ── FAVICON / BRAND ASSETS (self-hosted, no external deps) ───────
// The logo is a raster PNG (not hand-drawn vector), so /favicon.svg wraps
// the highest-resolution version in a minimal SVG container via <image> —
// this keeps every existing <img src="/favicon.svg"> reference across the
// site (nav.js, footer.js, admin/shell.js, admin.js) working unchanged,
// while still scaling crisply since the embedded source is 512x512.
export const FAVICON_SVG = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><image href="data:image/png;base64," width="64" height="64"/></svg>`;
export const FAVICON_ICO_B64 = "";
export const FAVICON_32_B64 = "";
export const FAVICON_16_B64 = "";
export const APPLE_TOUCH_B64 = "";
export const ICON512_B64 = "";

export function b64ToBytes(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

export const ICON_HEAD = `
<link rel="icon" href="/favicon.svg" type="image/svg+xml">
<link rel="icon" href="/favicon-32.png" sizes="32x32" type="image/png">
<link rel="icon" href="/favicon-16.png" sizes="16x16" type="image/png">
<link rel="shortcut icon" href="/favicon.ico">
<link rel="apple-touch-icon" href="/apple-touch-icon.png">
<link rel="manifest" href="/manifest.json">
<meta name="theme-color" content="#3556FF">`;

